import MenuJson from "./menus.json";
import { useI18n } from 'vue-i18n';

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  updated() {
    console.log(this.isLanguage)
    this.changeLanguage();
  },
  methods: {
    changeLanguage(){
      const { locale } = useI18n(); // Get locale from vue-i18n
      console.log("Before change:", locale.value);

      if (!this.isLanguage) {
        locale.value = 'en'; // Change to English
      } else {
        locale.value = 'kh'; // Change to Khmer
      }
    }
  },
};
